import 'admin_parse.dart';
class AdminMasjidModel { const AdminMasjidModel({required this.id,this.name,this.village,this.city,this.district,this.state,this.address,this.contactNo,this.description,this.welcomeMsg,this.status,this.imamUserId,this.imamName,this.usersCount,this.createdAt,this.updatedAt});
factory AdminMasjidModel.fromJson(Map<String,dynamic> json)=>AdminMasjidModel(id: readString(json,['id','_id','masjidId']), name: readNullableString(json,['name','masjidName']), village: readNullableString(json,['village']), city: readNullableString(json,['city']), district: readNullableString(json,['district']), state: readNullableString(json,['state']), address: readNullableString(json,['address']), contactNo: readNullableString(json,['contactNo','contactNumber']), description: readNullableString(json,['description']), welcomeMsg: readNullableString(json,['welcomeMsg','welcomeMessage']), status: readNullableString(json,['status']) ?? 'APPROVED', imamUserId: readNullableString(json,['imamUserId']), imamName: readNullableString(json,['imamName']) ?? (json['imam'] is Map<String,dynamic> ? readNullableString(json['imam'] as Map<String,dynamic>, ['fullName','name']) : null), usersCount: readInt(json,['usersCount','userCount','membersCount']), createdAt: readNullableString(json,['createdAt']), updatedAt: readNullableString(json,['updatedAt']));
final String id; final String? name,village,city,district,state,address,contactNo,description,welcomeMsg,status,imamUserId,imamName,createdAt,updatedAt; final int? usersCount;}
